mapper.sql:
SELECT COALESCE(NULLIF(tu.trace_id, ''), CONCAT('agent-', tu.id)) AS trace_id, 'agent' AS span_type, COALESCE(a.agent_name, '未知 Agent') AS name, CASE WHEN tu.success IS NULL OR tu.success = 1 THEN 1 ELSE 2 END AS status, tu.latency_ms AS duration_ms, tu.created_at AS started_at, tu.created_at AS finished_at, tu.error_message FROM token_usage tu LEFT JOIN agent a ON tu.agent_id = a.id WHERE tu.tenant_id = #{tenantId} AND tu.created_at >= #{since}
AND CASE WHEN tu.success IS NULL OR tu.success = 1 THEN 1 ELSE 2 END = #{status}
AND (tu.trace_id LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(a.agent_name, '未知 Agent') LIKE CONCAT('%', #{keyword}, '%') OR CONCAT('agent-', tu.id) LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:

UNION ALL

ORDER BY started_at DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM workflow_execution we
INNER JOIN workflow w ON we.workflow_id = w.id AND w.is_deleted = 0
WHERE we.tenant_id = #{tenantId}
AND we.started_at >= #{since}
AND we.status = #{status}

    AND (we.execution_id LIKE CONCAT('%', #{keyword}, '%')
         OR w.workflow_name LIKE CONCAT('%', #{keyword}, '%'))

SELECT COUNT(*)
FROM token_usage tu
LEFT JOIN agent a ON tu.agent_id = a.id
WHERE tu.tenant_id = #{tenantId}
AND tu.created_at >= #{since}

    AND CASE WHEN tu.success IS NULL OR tu.success = 1 THEN 1 ELSE 2 END = #{status}


    AND (tu.trace_id LIKE CONCAT('%', #{keyword}, '%')
         OR COALESCE(a.agent_name, '未知 Agent') LIKE CONCAT('%', #{keyword}, '%')
         OR CONCAT('agent-', tu.id) LIKE CONCAT('%', #{keyword}, '%'))
